namespace sv_c7e5d97bbd064c20926916202d05f57f.Services;

/// <summary>
/// Stub implementation of IChatService for development/testing.
/// Replace with a real implementation backed by a database or API.
/// </summary>
public class ChatService : IChatService
{
    private readonly List<Channel> _channels =
    [
        new(1, "general", "General discussion for the team", 3),
        new(2, "engineering", "Engineering topics and code reviews", 0),
        new(3, "random", "Off-topic banter and fun stuff", 1),
    ];

    private readonly List<Message> _messages =
    [
        new(1, 1, "Alice", "Hey team! How's the sprint going?", DateTime.Now.AddMinutes(-45), null, [new("👍", ["Bob", "Carol"])]),
        new(2, 1, "Bob", "Pretty good! Just finished the API refactor.", DateTime.Now.AddMinutes(-40), null, []),
        new(3, 1, "Carol", "Nice work Bob! I'll review it this afternoon.", DateTime.Now.AddMinutes(-38), null, [new("🎉", ["Alice"])]),
        new(4, 1, "Alice", "Great, let me know if you need help with the tests.", DateTime.Now.AddMinutes(-30), 1, []),
        new(5, 1, "Bob", "Will do, thanks!", DateTime.Now.AddMinutes(-28), 1, []),
        new(6, 2, "Dave", "Anyone looked at the new .NET release?", DateTime.Now.AddHours(-2), null, [new("👀", ["Alice", "Carol"])]),
        new(7, 3, "Carol", "Friday lunch plans?", DateTime.Now.AddHours(-1), null, []),
    ];

    public Task<List<Channel>> GetChannelsAsync() =>
        Task.FromResult(_channels.ToList());

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take) =>
        Task.FromResult(
            _messages
                .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
                .OrderBy(m => m.SentAt)
                .Skip(skip)
                .Take(take)
                .ToList());

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var id = _messages.Count > 0 ? _messages.Max(m => m.Id) + 1 : 1;
        var msg = new Message(id, channelId, "You", content, DateTime.Now, replyToId, []);
        _messages.Add(msg);
        return Task.FromResult(msg);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId) =>
        Task.FromResult(
            _messages
                .Where(m => m.ReplyToId == rootMessageId)
                .OrderBy(m => m.SentAt)
                .ToList());

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, ["You"]));
            }
        }
        return Task.CompletedTask;
    }

